<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Cheque Register</h1></div>
<div class="card shadow-sm"><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-3"><select id="status" class="form-select"><option value="">All</option><option>PENDING</option><option>CLEARED</option><option>BOUNCED</option></select></div><div class="col-md-3"><select id="direction" class="form-select"><option value="">IN + OUT</option><option value="IN">Received</option><option value="OUT">Issued</option></select></div></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>No.</th><th>Direction</th><th>Party</th><th>Bank</th><th>Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody id="rows"></tbody></table></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'))?>;function esc(v){return $('<div>').text(v??'').html();}function load(){$.getJSON(b+'cheques/data',{status:$('#status').val(),direction:$('#direction').val()},r=>{let x=$('#rows').empty();(r.data.rows||[]).forEach(a=>{let actions='';if(a.status==='PENDING')actions='<button class="btn btn-sm btn-success clear me-1" data-id="'+a.id+'">Clear</button><button class="btn btn-sm btn-outline-danger bounce" data-id="'+a.id+'">Bounce</button>';x.append('<tr><td>'+esc(a.cheque_no)+'</td><td>'+esc(a.direction)+'</td><td>'+esc(a.party_name||'')+'</td><td>'+esc(a.bank||'')+'</td><td>'+esc(a.cheque_date)+'</td><td>'+Number(a.amount).toFixed(2)+'</td><td>'+esc(a.status)+'</td><td>'+actions+'</td></tr>');});});}$('#status,#direction').on('change',load);$('#rows').on('click','.clear',function(){if(!confirm('Mark cheque cleared?'))return;$.post(b+'cheques/clear',{id:$(this).data('id'),date:new Date().toISOString().slice(0,10)}).done(r=>{alert(r.message);load();});});$('#rows').on('click','.bounce',function(){let reason=prompt('Bounce reason');if(!reason)return;$.post(b+'cheques/bounce',{id:$(this).data('id'),reason}).done(r=>{alert(r.message);load();});});load();});
</script>